from __future__ import annotations
import hashlib,json,sys,time
from pathlib import Path
import joblib,numpy as np,pandas as pd
from sklearn.ensemble import ExtraTreesClassifier,RandomForestClassifier
from sklearn.metrics import confusion_matrix,roc_auc_score
from sklearn.model_selection import GroupShuffleSplit
from sklearn.preprocessing import StandardScaler
HERE=Path(__file__).resolve(); ROOT=HERE.parents[1]; DATA=ROOT/'data'; REPORTS=ROOT/'reports'; sys.path.insert(0,str(HERE.parent))
from url_features import FULL_FEATURES,domain_group,extract_url_features
def metric(y,p,t):
 y=np.asarray(y,dtype=int); q=np.asarray(p)>=t; tn,fp,fn,tp=confusion_matrix(y,q,labels=[0,1]).ravel(); return {'n':int(len(y)),'benign_fpr':float(fp/max(1,tn+fp)),'malicious_recall':float(tp/max(1,fn+tp)),'confusion_matrix':[[int(tn),int(fp)],[int(fn),int(tp)]],'roc_auc':float(roc_auc_score(y,p))}
def threshold(y,p):
 grid=np.linspace(.0005,.9995,1999); y=np.asarray(y); s=np.sort(p[y==0]); b=np.sort(p[y==1]); fp=s.size-np.searchsorted(s,grid,'left'); tp=b.size-np.searchsorted(b,grid,'left'); f=fp/max(1,s.size); r=tp/max(1,b.size); ok=np.flatnonzero(f<=.01); i=ok[np.lexsort((grid[ok],f[ok],-r[ok]))[0]] if len(ok) else 0; return float(grid[i])
def main():
 df=pd.read_csv(DATA/'final_dataset.csv'); rem=pd.read_csv(DATA/'remediation_hard_negatives_v2.csv'); X=df[FULL_FEATURES].astype(np.float32); y=df.label.astype(int).to_numpy(); g=df.url.map(domain_group); tr,rest=next(GroupShuffleSplit(n_splits=1,test_size=.40,random_state=42).split(X,y,g)); vr,te=next(GroupShuffleSplit(n_splits=1,test_size=.50,random_state=42).split(X.iloc[rest],y[rest],g.iloc[rest])); vi,tei=rest[vr],rest[te]; sc=StandardScaler().fit(X.iloc[tr]); Xs=sc.transform(X); rx=sc.transform(pd.DataFrame([extract_url_features(u,FULL_FEATURES) for u in rem.url],columns=FULL_FEATURES)); ry=rem.label.astype(int).to_numpy(); hard=df.DatasetSource.to_numpy()=='hard'; fitX=np.vstack([Xs[tr],rx]); fity=np.concatenate([y[tr],ry]); sw=np.concatenate([np.ones(len(tr)),np.full(len(ry),5.)]); configs=[('challenger_hardsource_v2_extra40',ExtraTreesClassifier(n_estimators=40,max_depth=18,min_samples_leaf=2,n_jobs=1,class_weight='balanced',random_state=42)),('challenger_hardsource_v2_rf40',RandomForestClassifier(n_estimators=40,max_depth=18,min_samples_leaf=2,n_jobs=1,class_weight='balanced_subsample',random_state=42))]; out={}
 for name,m in configs:
  start=time.perf_counter(); m.fit(fitX,fity,sample_weight=sw); pv=m.predict_proba(Xs[vi])[:,1]; t=threshold(y[vi],pv); pt=m.predict_proba(Xs[tei])[:,1]; ph=m.predict_proba(Xs[hard])[:,1]; p=ROOT/'model'/'challengers'/name; p.mkdir(exist_ok=True); joblib.dump(m,p/'model.joblib'); joblib.dump(sc,p/'scaler.joblib'); r={'experiment_id':name,'architecture':type(m).__name__,'features':FULL_FEATURES,'seed':42,'threshold':t,'remediation_dataset_sha256':hashlib.sha256((DATA/'remediation_hard_negatives_v2.csv').read_bytes()).hexdigest(),'remediation_rows':len(rem),'remediation_weight':5.0,'fit_seconds':time.perf_counter()-start,'artifact':'model/challengers/'+name+'/model.joblib','validation':metric(y[vi],pv,t),'test':metric(y[tei],pt,t),'hard_source_holdout':metric(y[hard],ph,t),'serialized_model_bytes':int((p/'model.joblib').stat().st_size)}; (p/'metadata.json').write_text(json.dumps(r,indent=2),encoding='utf-8'); out[name]=r; print(name,json.dumps(r,indent=2),flush=True)
 stamp=pd.Timestamp.now(tz='UTC').isoformat(); (REPORTS/'URL_REMEDIATION_V4_EXPERIMENTS.json').write_text(json.dumps({'generated_at':stamp,'experiments':out,'frozen_champion_untouched':True},indent=2),encoding='utf-8'); (REPORTS/'URL_REMEDIATION_DATASET_REPORT.md').write_text('# URL-ML Remediation Dataset Report\n\nV1 introduced 980 source-diverse benign records across 49 registrable domains absent from the original dataset. V2 added 1,470 targeted security/account/payment/query variants over the same providers (2,450 total). No TEST, OOD, or hard-source row was copied or transformed.\n\nThe expansion targets the observed distribution shift: legitimate provider URLs with security semantics and non-empty paths/queries. It is intentionally source-diverse but still synthetic/template-generated; real-world adjudicated acquisition remains a residual risk.\n\nDataset hashes and counts are recorded in `data/remediation_hard_negatives_v1.json` and `data/remediation_hard_negatives_v2.json`.\n',encoding='utf-8');
 with (REPORTS/'EXPERIMENT_REGISTRY.jsonl').open('a',encoding='utf-8') as f:
  for n,r in out.items(): f.write(json.dumps({'experiment_id':n,'timestamp':stamp,'dataset_version':r['remediation_dataset_sha256'],'decision':'challenger','architecture':r['architecture'],'features':r['features'],'seed':42,'threshold':r['threshold'],'validation':r['validation'],'test':r['test'],'hard_source_holdout':r['hard_source_holdout'],'model_size_bytes':r['serialized_model_bytes']})+'\n')
if __name__=='__main__': main()
